<?php
namespace qqworld_collector\module\cloud_storage; use qqworld_collector\module\cloudStorage2; class tietuku extends cloudStorage2 { var $host = 'img.com'; public function init() { $this->protocol = $this->options->cloud_storage_tietuku_protocol; $this->token = $this->options->cloud_storage_tietuku_token; $this->silent_scanning = $this->options->cloud_storage_tietuku_silent_scanning; $this->delete_attachment_after_synced = $this->options->cloud_storage_joinmode_enabled ? 0 : $this->options->cloud_storage_tietuku_delete_attachment_after_synced; } public function upload($destination_path, $source_path) { if (!file_exists($source_path) || !filesize($source_path)) return false; $target_url = 'http://up.imgapi.com/'; if (function_exists('curl_file_create')) { $file = curl_file_create($source_path); } else { $file = '@' . realpath($source_path); } $post = array( 'from' => 'file', 'httptype' => $this->protocol, 'Token' => $this->token, 'file' => $file ); $ch = curl_init(); curl_setopt($ch, CURLOPT_URL,$target_url); curl_setopt($ch, CURLOPT_POST, true); curl_setopt($ch, CURLOPT_POSTFIELDS, $post); curl_setopt($ch, CURLOPT_RETURNTRANSFER, true); $result = curl_exec($ch); curl_close($ch); $result = json_decode($result, true); if (empty($result) || isset($result['code'])) { do_action( 'qqworld-collector-log', $this->log_id, 'tietuku failed: ', print_r($result, true) ); return false; } else return $result['linkurl']; } public function add_could_storage_form($guid) { $this->accessed = $this->is_current && $this->token; require QQWORLD_COLLECTOR_DIR . 'pages' . DIRECTORY_SEPARATOR . 'cloudStorage-'.$this->guid.'.php'; } } ?>